import itertools
import json

def main():
    # Define the attributes for each category
    houses = [1, 2]
    names = ["Eric", "Arnold"]
    months = ["sept", "april"]
    colors = ["yellow", "red"]

    solution = None

    # Iterate over all possible permutations for names, months, and colors
    for name_perm in itertools.permutations(names):
        for month_perm in itertools.permutations(months):
            for color_perm in itertools.permutations(colors):
                # Constraint 2: The person whose birthday is in April is in the first house.
                if month_perm[0] != "april":
                    continue
                # Constraint 3: The person who loves yellow is not in the first house.
                if color_perm[0] == "yellow":
                    continue
                # Constraint 1: Eric is the person who loves yellow.
                valid = True
                for i in range(len(houses)):
                    if name_perm[i] == "Eric" and color_perm[i] != "yellow":
                        valid = False
                        break
                    if color_perm[i] == "yellow" and name_perm[i] != "Eric":
                        valid = False
                        break
                if not valid:
                    continue

                # Record solution if all constraints are met.
                solution = []
                for i in range(len(houses)):
                    house_number = str(houses[i])
                    row = [house_number, name_perm[i], month_perm[i], color_perm[i]]
                    solution.append(row)

                break
            if solution is not None:
                break
        if solution is not None:
            break

    # Prepare the output in the required JSON format.
    output = {
        "solution": {
            "header": ["House", "Name", "birthday month", "favorite color"],
            "rows": solution
        }
    }
    print(json.dumps(output))

if __name__ == "__main__":
    main()
